edits.after:
export function initCheckboxes() {
  document.querySelectorAll('[data-module="nhsuk-checkboxes"]').forEach((container) => {
    container.querySelectorAll('input[type="checkbox"]').forEach((checkbox) => {
      checkbox.addEventListener('change', () => {
        if (checkbox.checked && checkbox.hasAttribute('data-checkbox-exclusive')) {
          const group = checkbox.getAttribute('data-checkbox-exclusive-group');
          if (group) {
            container.querySelectorAll(`input[type="checkbox"][data-checkbox-exclusive-group="${group}"]`).forEach((other) => {
              if (other !== checkbox && other.checked) {
                other.checked = false;
                other.dispatchEvent(new Event('change', { bubbles: true }));
              }
            });
          } else {
            container.querySelectorAll('input[type="checkbox"]').forEach((other) => {
              if (other !== checkbox && other.checked) {
                other.checked = false;
                other.dispatchEvent(new Event('change', { bubbles: true }));
              }
            });
          }
        }
      });
    });
  });
}
